package ro.leo.visual;
import android.content.*;import android.os.Bundle;import java.io.*;import java.util.*;import org.json.*;
/** Separate additive agenda/SMS archive; never changes Telecom/SmsManager. */
public final class PeopleBackupActivity extends LeoActivity {
 private boolean busy,contacts=true,sms=true;private File boundary;private JSONObject data;private boolean restoreContacts,restoreSms;
 protected void onCreate(Bundle b){super.onCreate(b);String path=getIntent().getStringExtra("file");if(path==null)home();else preview(new File(path));}
 private void home(){list("Contacte și SMS · backup",Arrays.asList("Contacte · "+(contacts?"Include":"Exclude"),"SMS · "+(sms?"Include":"Exclude"),"Exportă selecția","Importă din fișier","Copii automate locale"),0,new Choice(){public void pick(int i){if(i==0){contacts=!contacts;home();}else if(i==1){sms=!sms;home();}else if(i==2){if(!contacts&&!sms){notice("Alege datele de exportat");return;}destinations();}else if(i==3)roots();else{boundary=new File(getFilesDir(),"documents/People-rollback");boundary.mkdirs();browse(boundary);}}},"",null);}
 private void destinations(){final ArrayList<File> dirs=new ArrayList<File>();ArrayList<String> labels=new ArrayList<String>();for(Map.Entry<String,File> e:LeoFileProvider.roots(this).entrySet()){dirs.add(new File(e.getValue(),e.getKey().equals("leo")?"Backup":"Documents/LeoBackups"));labels.add(e.getKey().equals("phone")?"Telefon":e.getKey().equals("leo")?"Documente Leo":"Card SD");}list("Export personal necriptat",labels,0,new Choice(){public void pick(int i){export(dirs.get(i));}},"",null);back=new Runnable(){public void run(){home();}};}
 private void waiting(String title){busy=true;begin(title);root.addView(text("Operație locală…",18));footer("","","Așteaptă");}
 private void export(final File folder){waiting("Export contacte / SMS");worker.execute(new Runnable(){public void run(){try{final File result=PeopleArchive.export(PeopleBackupActivity.this,folder,contacts,sms);ui(new Runnable(){public void run(){busy=false;begin("Export salvat");root.addView(text(result.getName()+"\n\nDate personale, fără criptare. Fișierul poate fi deschis din Fișiere Leo.",17));back=new Runnable(){public void run(){home();}};footer("","","Înapoi");}});}catch(final Exception e){fail(e);}}});}
 private void roots(){final ArrayList<File> dirs=new ArrayList<File>(LeoFileProvider.roots(this).values());ArrayList<String> labels=new ArrayList<String>();for(File d:dirs)labels.add(d.getName());list("Caută arhiva personală",labels,0,new Choice(){public void pick(int i){boundary=dirs.get(i);browse(boundary);}},"",null);back=new Runnable(){public void run(){home();}};}
 private void browse(final File folder){try{if(!LeoFileProvider.inside(boundary,folder))throw new IOException("Folder invalid");File[] all=folder.listFiles();if(all==null)throw new IOException("Folder inaccesibil");Arrays.sort(all);final ArrayList<File> files=new ArrayList<File>();ArrayList<String> labels=new ArrayList<String>();for(File f:all)if(files.size()<300&&LeoFileProvider.inside(boundary,f)&&(f.isDirectory()||f.getName().endsWith(".leo-people.json"))){files.add(f);labels.add((f.isDirectory()?"▸ ":"")+f.getName());}list("Arhive contacte / SMS",labels,0,new Choice(){public void pick(int i){if(files.get(i).isDirectory())browse(files.get(i));else preview(files.get(i));}},"",null);back=new Runnable(){public void run(){if(folder.equals(boundary))roots();else browse(folder.getParentFile());}};}catch(Exception e){notice("Folder inaccesibil");}}
 private void preview(final File file){boolean allowed=false;try{for(File dir:LeoFileProvider.roots(this).values())if(LeoFileProvider.inside(dir,file))allowed=true;}catch(IOException ignored){}if(!allowed){home();notice("Fișier în afara stocării permise");return;}waiting("Verific arhiva");worker.execute(new Runnable(){public void run(){try{final JSONObject parsed=PeopleArchive.read(file);ui(new Runnable(){public void run(){data=parsed;busy=false;restoreContacts=false;restoreSms=false;selection();}});}catch(Exception e){fail(e);}}});}
 private void selection(){list("Alege ce restaurezi",Arrays.asList("Contacte · "+data.optJSONArray("contacts").length()+" · "+(restoreContacts?"Da":"Nu"),"SMS · "+data.optJSONArray("sms").length()+" · "+(restoreSms?"Da":"Nu"),"Verifică duplicatele","Adăugare locală · fără înlocuire","SMS-urile nu sunt retrimise"),0,new Choice(){public void pick(int i){if(i==0){restoreContacts=!restoreContacts;selection();}else if(i==1){restoreSms=!restoreSms;selection();}else if(i==2)plan();}},"",null);back=new Runnable(){public void run(){home();}};}
 private void plan(){if(!restoreContacts&&!restoreSms){notice("Alege Contacte și/sau SMS");return;}waiting("Verific duplicatele");worker.execute(new Runnable(){public void run(){try{final int[] plan=PeopleArchive.plan(PeopleBackupActivity.this,data,restoreContacts,restoreSms);ui(new Runnable(){public void run(){busy=false;options("Adăugare: "+plan[0]+" contacte / "+plan[2]+" SMS",new String[]{"Anulează", "Duplicate omise · "+(plan[1]+plan[3]),"Confirmă restaurarea"},new Choice(){public void pick(int i){if(i==2)merge();else selection();}});}});}catch(Exception e){fail(e);}}});}
 private void merge(){waiting("Restaurez selecția");worker.execute(new Runnable(){public void run(){try{PeopleArchive.export(PeopleBackupActivity.this,new File(getFilesDir(),"documents/People-rollback"),restoreContacts,restoreSms);final int[] n=PeopleArchive.merge(PeopleBackupActivity.this,data,restoreContacts,restoreSms);ui(new Runnable(){public void run(){busy=false;begin("Restaurare terminată");root.addView(text("Adăugate: "+n[0]+" contacte, "+n[2]+" SMS.\n\nDuplicate omise: "+(n[1]+n[3])+".\n\nCopia inițială: Documente Leo / People-rollback.",17));back=new Runnable(){public void run(){home();}};footer("","","Înapoi");}});}catch(Exception e){fail(new IOException("Operație oprită; unele contacte pot fi adăugate. Reîncercarea omite duplicatele. Copia inițială este păstrată local.",e));}}});}
 private void fail(final Exception e){ui(new Runnable(){public void run(){busy=false;home();notice(e.getMessage()==null?"Operație eșuată":e.getMessage());}});}
 public void onBackPressed(){if(!busy)super.onBackPressed();}public boolean onKeyDown(int key,android.view.KeyEvent e){if(busy&&key==android.view.KeyEvent.KEYCODE_BACK)return true;return super.onKeyDown(key,e);}
}
